/* Dedicated class selection; existing pins/configuration remain compatible with old saves. */
playPages.splice(playPages.findIndex(p=>p[1]===5),0,['Классы',12]);
let classCategory='Классы',classQuery='';
const CLASS_ENTRIES=RULE_ENTRIES.filter(e=>['Классы','Престиж-классы'].includes(e.category));
function classRows(entry){const rows=ruleTable(entry.category).rows,result=[];for(let i=entry.row-1;i<rows.length&&(i===entry.row-1||!rows[i][0]);i++)result.push(rows[i]);return result;}
function classParent(entry){if(entry.category==='Классы')return entry;const requirements=String(classRows(entry)[0]?.[1]||'').toLowerCase();return CLASS_ENTRIES.find(e=>e.category==='Классы'&&requirements.includes('класс '+e.title.toLowerCase()));}
function selectedClassEntries(){return selectedEffectSources().filter(e=>['Классы','Престиж-классы'].includes(e.category));}
function classFixedSkill(entry,skill){
 const name=effectNorm(skillEffectName(skill)),key=combatKey(skill)||'',cfg=sourceConfig(entry.id),matches=p=>p.test(name);
 if(entry.title==='Боец')return matches(/^(атлетика|акробатика|стойкость|метание)$/)||key===('Ближний бой '+(cfg.style==='STR'?'силовой стиль':cfg.style==='DEX'?'ловкий стиль':'не выбран'));
 if(entry.title==='Стрелок')return matches(/^(наблюдательность|стойкость)$/);
 if(entry.title==='Псион')return matches(/^(стойкость|стойкостьразума|псистойкость)$/);
 if(entry.title==='Авантюрист')return matches(/скрытность|карманник|взломзамков|наблюдательность|азартныеигры/);
 if(entry.title==='Техник')return matches(/^ремонт/);
 if(entry.title==='Ученый')return matches(/^(наблюдательность|разговор|убеждение)$/);
 if(entry.title==='Артист')return matches(/^(разговор|убеждение)$/);
 if(entry.title==='Пси-универсал')return isPsiSkill(skill);
 if(entry.title==='Знаток')return matches(/знани/);
 const parent=classParent(entry);if(parent&&/все .*навык/i.test(String(classRows(entry)[0]?.[2]||''))&&classFixedSkill(parent,skill))return true;
 const text=String(classRows(entry)[0]?.[2]||'');return text.split(/[,\n\r]/).some(t=>{const n=effectNorm(t);return n.length>3&&!/все|один|любо|выбор|навык|аналог/.test(t.toLowerCase())&&(n===name||n===effectNorm(key));});
}
const beforeClassSkillSources=classSkillSources;
classSkillSources=function(skill){const result=beforeClassSkillSources(skill).filter(name=>!CLASS_ENTRIES.some(e=>e.title===name));for(const entry of selectedClassEntries()){if(sourceConfig(entry.id).enabled===false)continue;const cfg=sourceConfig(entry.id);if(classFixedSkill(entry,skill)||cfg.classSkills?.includes(skillIdentity(skill)))result.push(entry.title);}return [...new Set(result)];};
function setClassSelection(id,selected){const entry=CLASS_ENTRIES.find(e=>e.id===id);if(!entry)throw Error('Класс не найден.');const auto=selectedClassEntries().find(e=>e.id===id)?.automatic;if(auto&&!selected)throw Error('Этот класс предоставлен расой. Его можно отключить в настройках источника.');if(selected&&!state.play.pinned.includes(id))state.play.pinned.push(id);if(!selected)state.play.pinned=state.play.pinned.filter(key=>key!==id);}
function renderClassCard(entry,selected=false){const rows=classRows(entry),cfg=sourceConfig(entry.id),automatic=selectedClassEntries().find(e=>e.id===entry.id)?.automatic;return `<article class="class-card"><div class="section-heading"><h3>${esc(entry.title)}</h3><button data-class-select="${entry.id}" aria-pressed="${selected}">${selected?'Убрать':'Выбрать'}</button></div>${automatic?'<small>Предоставлен расой</small>':''}<p class="class-requirements"><b>Требования:</b> ${esc(rows.map(r=>r[1]).filter(Boolean).join('; '))}</p><details><summary>Классовые навыки, пределы и особенности</summary><dl><dt>Классовые навыки</dt><dd>${esc(rows.map(r=>r[2]).filter(Boolean).join('\n'))}</dd><dt>Дополнительные навыки</dt><dd>${esc(rows.map(r=>r[3]).filter(Boolean).join('; '))}</dd><dt>Максимумы характеристик</dt><dd>${esc(rows.map(r=>r[4]).filter(Boolean).join('; '))}</dd></dl><p class="rule-text">${esc(rows.map(r=>r[5]).filter(Boolean).join('\n'))}</p><a href="${entry.url}" target="_blank" rel="noopener">Sacralic ↗</a></details>${selected?`<div class="ability-actions">${(ABILITY_ACTIONS[entry.title]||[]).map((a,i)=>'<button data-ability-use="'+entry.id+'" data-action-index="'+i+'" '+(cfg.enabled===false||abilityUses(entry,a)>=abilityLimit(a)?'disabled':'')+'>'+esc(a.label)+(Number.isFinite(abilityLimit(a))?' · '+Math.max(0,abilityLimit(a)-abilityUses(entry,a))+'/'+abilityLimit(a):'')+'</button>').join('')}<button data-effect-source="${entry.id}">⚙ Бонусы, уровень и условия</button></div><small>${cfg.enabled===false?'Бонусы выключены':'Бонусы применяются автоматически'} · уровень ${effectsForSource(entry).level}</small><details><summary>Выбрать классовые навыки</summary><p>Отметьте варианты, указанные в правиле как выбор, и дополнительные классовые навыки. Фиксированные навыки учитываются автоматически.</p>${state.skills.map(skill=>`<label class="check-row"><input type="checkbox" data-class-skill="${entry.id}" data-skill-id="${skillIdentity(skill)}" ${classFixedSkill(entry,skill)||cfg.classSkills?.includes(skillIdentity(skill))?'checked':''} ${classFixedSkill(entry,skill)?'disabled':''}>${esc(skill[0])}</label>`).join('')}</details>`:''}</article>`;}
function renderClassesPage(){const selected=selectedClassEntries();return `<section class="panel classes-page"><div class="section-heading"><h2>Классы и престиж-классы</h2></div><div class="class-selected"><h3>Выбранные</h3>${selected.map(e=>renderClassCard(e,true)).join('')||'<p>Выберите базовый класс или престиж-класс из списка ниже.</p>'}</div><div class="class-picker-controls"><div class="filter-tabs">${['Классы','Престиж-классы'].map(c=>`<button data-class-category="${c}" aria-pressed="${classCategory===c}">${c}</button>`).join('')}</div><label>Поиск<input id="class-search" value="${esc(classQuery)}" placeholder="Название или требование"></label></div><p class="muted">Требования показаны для проверки игроком. Выбор остаётся доступным для переноса существующих персонажей и решений ведущего.</p><div class="class-catalog">${CLASS_ENTRIES.filter(e=>e.category===classCategory&&!selected.some(s=>s.id===e.id)&&effectNorm(e.title+' '+e.text).includes(effectNorm(classQuery))).map(e=>renderClassCard(e)).join('')}</div></section>`;}
const beforeClassesAbilities=renderAbilities;
renderAbilities=function(){return '<section class="panel"><div class="section-heading"><h2>Классы персонажа</h2><button data-page="12">Выбрать класс / престиж →</button></div>'+selectedClassEntries().map(e=>'<button data-effect-source="'+e.id+'">'+esc(e.title)+'</button>').join('')+'</section>'+beforeClassesAbilities();};
document.addEventListener('click',event=>{const b=event.target.closest('[data-class-select],[data-class-category]');if(!b)return;event.preventDefault();event.stopImmediatePropagation();try{if(b.dataset.classCategory)classCategory=b.dataset.classCategory;else{const entry=CLASS_ENTRIES.find(e=>e.id===b.dataset.classSelect),selected=selectedClassEntries().some(e=>e.id===entry.id);setClassSelection(entry.id,!selected);}save();render();}catch(error){toast(error.message);}},true);
document.addEventListener('change',event=>{const el=event.target;if(el.id==='class-search'){event.stopImmediatePropagation();classQuery=el.value;render();return;}if(!el.dataset.classSkill)return;event.stopImmediatePropagation();const cfg=state.effects.sources[el.dataset.classSkill]??={},skills=new Set(cfg.classSkills||[]);if(el.checked)skills.add(el.dataset.skillId);else skills.delete(el.dataset.skillId);cfg.classSkills=[...skills];save();render();},true);
render();
